export const CBE_COURSES = ACADEMY_COURSES.filter((c) => c.track_id === 'cbe');

export const ACADEMY_BY_CODE = Object.fromEntries(ACADEMY_COURSES.map((c) => [c.code, c]));
export const ACADEMY_BY_SLUG = Object.fromEntries(ACADEMY_COURSES.map((c) => [c.slug, c]));

export const PUBLISHED_COURSES = ACADEMY_COURSES;

export function getCoursesByTrack(trackId) {
  return ACADEMY_COURSES.filter((c) => c.track_id === trackId);
}

export function getCourseBySlug(slug) {
  return ACADEMY_BY_SLUG[slug] || null;
}

export function getCourseByCode(code) {
  return ACADEMY_BY_CODE[code] || null;
}

// KES price estimate at ~130 KES per USD
export const KES_RATE = 130;

export function priceKes(usd) {
  return (usd || 0) * KES_RATE;
}
